func (e *Executor) AreAllResultsCollected() bool {
	allCollected := true

	e.RunningCode.Range(func(k string, _ *llx.CodeBundle) bool {
		if _, ok := e.ScoreResults.Load(k); !ok {
			allCollected = false
			return false
		}
		return true
	})

	return allCollected
}

